ht:38px;overflow:hidden;margin:7px 0;color:var(--muted);font-size:11px;line-height:1.6}.price{display:flex;justify-content:space-between;align-items:end;margin-top:14px}.price strong{font-size:19px;color:var(--brand)}.old{font-size:11px;color:#9aa39d;text-decoration:line-through}.badge{font-size:9px;font-weight:900;padding:5px 7px;border-radius:7px;background:#fff0d1;color:#a86a00}.empty{text-align:center;padding:60px;color:var(--muted)}.footer{padding:30px 20px;text-align:center;background:#10271f;color:#b9cbc4}.footer strong{color:#fff}.modal{position:fixed;inset:0;z-index:20;display:none;align-items:end;justify-content:center;padding:20px;background:#07120dc9;backdrop-filter:blur(8px)}.modal.open{display:flex}.modal-card{width:min(500px,100%);padding:25px;border-radius:28px;background:var(--paper);box-shadow:0 25px 80px #0005}.modal-head{display:flex;justify-content:space-between;align-items:center}.modal-head h3{margin:0;font-family:Georgia,serif;font-size:28px}.close{width:38px;height:38px;border:0;border-radius:50%;background:#e9ece6;cursor:pointer}.wifi-row{margin-top:14px;padding:15px;border:1px solid var(--line);border-radius:15px}.wifi-row small{display:block;color:var(--muted)}.wifi-row span{display:flex;align-items:center;justify-content:space-between;margin-top:5px}.copy{border:0;background:var(--brand);color:#fff;padding:7px 10px;border-radius:8px;cursor:pointer}.info-list{display:grid;gap:12px;margin-top:18px}.info-list div{padding:14px;border-radius:14px;background:#eef1eb}.info-list small{display:block;color:var(--muted);margin-bottom:4px}@media(max-width:700px){.shell{padding:0 14px}.hero{min-height:420px;border-radius:0 0 30px 30px}.hero-copy{padding:45px 0 75px}.quick{grid-template-columns:repeat(2,1fr);gap:9px;margin-top:-34px}.quick button,.quick a{min-height:116px;padding:15px}.catalog-head{display:block}.search{margin-top:18px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.photo{height:125px}.product-body{padding:12px}.product p