<script>let active='all';function selectCategory(btn){active=btn.dataset.cat;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===btn));filterMenu()}function filterMenu(){const q=document.getElementById('search').value.toLocaleLowerCase('tr');document.querySelectorAll('.product').forEach(p=>p.hidden=!((active==='all'||p.dataset.cat===active)&&p.dataset.name.includes(q)));document.querySelectorAll('[data-section]').forEach(s=>s.hidden=(active!=='all'&&s.dataset.section!==active)||![...s.querySelectorAll('.product')].some(p=>!p.hidden))}function openModal(id){document.getElementById(id).classList.add('open')}function closeModal(id){document.getElementById(id).classList.remove('open')}async function copyText(text,button){try{await navigator.clipboard.writeText(text)}catch(e){const input=document.createElement('input');input.value=text;document.body.appendChild(input);input.select();document.execCommand('copy');input.remove()}button.textContent='Kopyalandı'}</script>
@if($diningTable && $orderingEnabled)
<script>
const cartKey=@json('diji-cart-'.$diningTable->qr_token);let cart=JSON.parse(sessionStorage.getItem(cartKey)||'{}');
@if(session('order_success')) cart={};sessionStorage.removeItem(cartKey); @endif
function money(value){return new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(value)}
function escapeText(value){const el=document.createElement('span');el.textContent=value;return el.innerHTML}
function saveCart(){sessionStorage.setItem(cartKey,JSON.stringify(cart));const rows=Object.values(cart);const count=rows.reduce((sum,row)=>sum+row.quantity,0);const total=rows.reduce((sum,row)=>sum+(row.price*row.quantity),0);document.getElementById('cartCount').textContent=count+' ürün';document.getElementById('cartTotal').textContent=money(total);document.getElementById('cartBar').classList.toggle('show',count>0)}
function addCart(product){cart[product.id]??={...product,quantity:0};cart[product.id].quantity=Math.min(20,cart[product.id].quantity+1);saveCart()}
function changeQty(id,delta){if(!cart[id])return;cart[id].quantity+=delta;if(cart[id].quantity<=0)delete cart[id];saveCart();renderCart()}
function renderCart(){const root=document.getElementById('cartItems');const rows=Object.values(cart);root.innerHTML=rows.length?rows.map(row=>`<div class="cart-item"><div><b>${escapeText(row.name)}</b><small>${money(row.price)} × ${row.quantity}</small></div><div class="qty"><button type="button" onclick="changeQty(${Number(row.id)},-1)">−</button><b>${row.quantity}</b><button type="button" onclick="changeQty(${Number(row.id)},1)">+</button></div></div>`).join(''):'<div class="empty">Sepetiniz boş.</div>'}
function prepareOrder(){const rows=Object.values(cart);if(!rows.length)return false;const inputs=document.getElementById('orderInputs');inputs.innerHTML='';rows.forEach((row,index)=>{[['product_id',row.id],['quantity',row.quantity]].forEach(([key,value])=>{const input=document.createElement('input');input.type='hidden';input.name=`items[${index}][${key}]`;input.value=value;inputs.appendChild(input)})});document.getElementById('submitOrder').disabled=true;document.getElementById('submitOrder').textContent='Sipariş gönderiliyor...';return true}
saveCart();
</script>
@endif
